// Package attest signs and verifies paranoid trust reports.
//
// Two signing modes. The default, local, uses a stdlib crypto/ed25519
// keypair generated by `paranoid attest keygen` and never touches the
// network. The second, keyless, shells out to the cosign CLI (the
// same pattern this project already uses for git and docker: shell
// out to a real binary instead of importing its SDK) to run Sigstore's
// keyless signing flow, which does use the network, but only when the
// caller explicitly asks for it with --sign keyless.
//
// A signature is always a sidecar file next to the signed report; it
// never becomes part of the report's own JSON schema.
package attest

import (
	"os"
	"path/filepath"
)

// Mode names a signing or verification path.
type Mode string

// The two supported modes.
const (
	ModeLocal   Mode = "local"
	ModeKeyless Mode = "keyless"
)

// SigFormatVersion is the version of the local signature envelope
// (attest.LocalSignature) written to a .sig file by local signing.
// It is independent of finding.SchemaVersion: the signature is a
// sidecar artifact, never part of the report itself, so a report
// schema bump never forces a signature format bump or vice versa.
const SigFormatVersion = 1

// KeyFileName and PubKeyFileName are the file names `attest keygen`
// writes inside the config directory: a private key and its public
// counterpart, the same naming convention ssh-keygen uses.
const (
	KeyFileName    = "attest.key"
	PubKeyFileName = "attest.key.pub"
)

// DefaultConfigDir resolves ${XDG_CONFIG_HOME:-~/.config}/paranoid,
// the same pattern internal/registry uses for its own cache directory
// (${XDG_CACHE_HOME:-~/.cache}/paranoid). Returns "" if no home
// directory can be found.
func DefaultConfigDir() string {
	if xdg := os.Getenv("XDG_CONFIG_HOME"); xdg != "" {
		return filepath.Join(xdg, "paranoid")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "paranoid")
}

// DefaultKeyPath is the default private key location `attest keygen`
// writes to and `verify --sign local` reads from, unless overridden.
func DefaultKeyPath() string { return filepath.Join(DefaultConfigDir(), KeyFileName) }

// DefaultPubKeyPath is the default public key location `attest
// keygen` writes to and `attest verify` reads from, unless overridden
// by --key.
func DefaultPubKeyPath() string { return filepath.Join(DefaultConfigDir(), PubKeyFileName) }
